<?php
namespace Tests\Feature;
use App\Models\{User,Apprentice,TutorGroup,TrainingSession,TimetableRoom as Room,TimetableStaffWindow as Window,TimetablePlan as Plan,TimetablePlanEntry as Entry,TimetableFlexibleDay as Day,TimetableGroupBrief as Brief,TimetableCoverAllocation as Cover,TimetableGovernanceState as State,TimetableGovernanceRole as Role,TimetableAllocationControl as Control,TimetableStaffSection as Section};
use App\Support\{CentrePlanning as P,CentreTimetable as T,TimetableDuties as D,TimetableCover as C,ReviewedImports,TimetableGovernance as G};
use Illuminate\Foundation\Testing\LazilyRefreshDatabase;
use Illuminate\Support\Facades\{DB,Mail,Http};
use Illuminate\Support\Str;
use Illuminate\Validation\ValidationException;
use Tests\Support\AuditFault;
use Tests\TestCase;
class TimetableGovernanceTest extends TestCase {
 use LazilyRefreshDatabase;
 private function fixture():array {$admin=User::factory()->create(['role'=>'admin']);$planner=User::factory()->create(['role'=>'manager']);P::grant($admin,1,$planner,0,true);$tutor=User::factory()->create(['role'=>'tutor']);$cover=User::factory()->create(['role'=>'tutor']);$other=User::factory()->create(['role'=>'tutor']);$group=TutorGroup::factory()->create(['tutor_id'=>$tutor->id]);$a=Apprentice::factory()->create(['tutor_group_id'=>$group->id,'tutor_id'=>$tutor->id,'start_date'=>'2026-09-07']);$room=Room::where('site','Doncaster')->first();P::room($admin,1,$room,1,['capacity'=>8,'uses'=>['Teaching','Admin','Review'],'active'=>true]);$room->refresh();$date=today()->addDays(7)->startOfWeek()->addDay()->toDateString();$dates=P::dates($date,2);foreach([$tutor,$cover,$other]as$u){P::windows($admin,1,$u,$dates,ReviewedImports::hash(P::windowSource($u,$dates)),true,'08:00','18:00');}$d=['staff_id'=>$tutor->id,'date'=>$date,'weeks'=>2,'start'=>'09:00','end'=>'16:00','kind'=>'Teaching','site'=>'Doncaster','room_id'=>$room->id,'group_id'=>$group->id,'title'=>'Fictional whole-day class','headcount'=>4];return compact('admin','planner','tutor','cover','other','group','a','room','date','dates','d');}
 private function reject(callable $fn):void {try{$fn();$this->fail('Expected checked rejection');}catch(ValidationException $e){$this->assertNotEmpty($e->errors());}}
 private function flex(array $f,?User $who=null):Day {$who??=$f['cover'];D::saveDays($f['planner'],1,$who,$f['planner'],$f['dates'],ReviewedImports::hash(D::preview($who,$f['dates'])),'09:00','16:00');return D::day($who->id,$f['date']);}
 private function plan(array $f,?array $data=null):Plan {$p=P::save($f['planner'],1,null,0,(string)Str::uuid(),$data??$f['d']);P::check($f['planner'],1,$p,1,true);P::publish($f['planner'],1,$p->refresh(),2);return $p->refresh();}
 private function proposal(array $f):Cover {$p=$this->plan($f);$day=$this->flex($f);$e=Entry::where('plan_id',$p->id)->orderBy('work_date')->first();return C::prepare($f['planner'],1,$e,$day,(string)Str::uuid(),'PRIVATE-SUITABILITY-REFERENCE');}
 private function activate(array $f):Cover {$c=$this->proposal($f);C::check($f['planner'],1,$c,1);C::publish($f['planner'],1,$c->refresh(),2);return $c->refresh();}

 private function rev():int {return State::find(1)->revision;}
 private function role(User $actor,User $target,string $role='centre_manager',bool $restricted=false,bool $lock=false):void {G::role($actor,1,$target,Role::find($target->id)?->version??0,$this->rev(),$role,$restricted,$lock,'Fictional reviewed timetable decision');}
 public function test_centre_manager_can_plan_without_portal_private_manager_permission():void {$f=$this->fixture();$this->role($f['admin'],$f['other']);$this->assertTrue(P::allowed($f['other']));$this->assertFalse(\App\Support\LearningAccess::manager($f['other']));$this->assertSame('tutor',$f['other']->fresh()->role);$this->actingAs($f['other'])->get('/centre-planning/governance')->assertOk();$this->get('/ceo/emergency')->assertForbidden();}
 public function test_centre_manager_can_manage_other_subordinate_access():void {$f=$this->fixture();$this->role($f['admin'],$f['other']);$this->role($f['other'],$f['cover']);$this->assertTrue(P::allowed($f['cover']));$this->role($f['other'],$f['cover'],'viewer');$this->assertFalse(P::allowed($f['cover']));}
 public function test_subordinate_cannot_restrict_ceo():void {$f=$this->fixture();$ceo=User::factory()->create(['role'=>'ceo']);$this->reject(fn()=>$this->role($f['admin'],$ceo,'viewer',true));$this->assertTrue(P::allowed($ceo));}
 public function test_ceo_protected_role_cannot_be_overridden_by_admin_or_cm():void {$f=$this->fixture();$ceo=User::factory()->create(['role'=>'ceo']);$this->role($ceo,$f['other'],'viewer',true,true);$this->reject(fn()=>$this->role($f['admin'],$f['other']));$this->assertFalse(P::allowed($f['other']));$this->role($ceo,$f['other'],'centre_manager',false,false);$this->assertTrue(P::allowed($f['other']));}
 public function test_admin_cannot_create_ceo_protected_decision():void {$f=$this->fixture();$this->reject(fn()=>$this->role($f['admin'],$f['other'],'centre_manager',false,true));$this->assertDatabaseCount('timetable_governance_roles',0);}
 public function test_restricted_editor_can_read_roles_but_cannot_write():void {$f=$this->fixture();$this->role($f['admin'],$f['other'],'centre_manager',true);$this->assertTrue(G::manager($f['other']));$this->assertFalse(P::allowed($f['other']));$this->actingAs($f['other'])->get('/centre-planning/governance')->assertOk();$this->get('/centre-planning/plans/new')->assertForbidden();try{$this->role($f['other'],$f['cover']);$this->fail('Expected forbidden');}catch(\Symfony\Component\HttpKernel\Exception\HttpException $e){$this->assertSame(403,$e->getStatusCode());}}
 public function test_ceo_pause_holds_all_subordinate_planning_and_preserves_published_reservations():void {$f=$this->fixture();$p=$this->plan($f);$ceo=User::factory()->create(['role'=>'ceo']);G::pause($ceo,1,$this->rev(),true,'Fictional pause');$this->assertFalse(P::allowed($f['admin']));$this->assertFalse(P::allowed($f['planner']));$this->assertTrue(P::allowed($ceo));$this->assertTrue(P::published($p));$this->assertNotEmpty(P::busy([$f['date']])['rows']);G::pause($ceo,1,$this->rev(),false,'Fictional restore');$this->assertTrue(P::allowed($f['planner']));}
 public function test_admin_cannot_use_ceo_pause():void {$f=$this->fixture();$this->actingAs($f['admin'])->post('/centre-planning/governance/pause',['version'=>0,'revision'=>$this->rev(),'paused'=>1,'note'=>'No','confirmed'=>1])->assertForbidden();$this->assertFalse(State::find(1)->editing_paused);}
 public function test_stale_global_revision_prevents_overwriting_another_manager():void {$f=$this->fixture();$rev=$this->rev();$this->role($f['admin'],$f['other']);$this->reject(fn()=>G::role($f['admin'],1,$f['cover'],0,$rev,'centre_manager',false,false,'Stale'));$this->assertDatabaseCount('timetable_governance_roles',1);}
 public function test_stale_role_version_rejected_even_with_current_global_revision():void {$f=$this->fixture();$this->role($f['admin'],$f['other']);$this->reject(fn()=>G::role($f['admin'],1,$f['other'],0,$this->rev(),'viewer',false,false,'Stale'));$this->assertTrue(P::allowed($f['other']));}
 public function test_primary_role_change_invalidates_delegation():void {$f=$this->fixture();$this->role($f['admin'],$f['other']);$f['other']->forceFill(['role'=>'careers_adviser'])->save();$this->assertFalse(P::allowed($f['other']->fresh()));}
 public function test_inactive_or_stale_auth_actor_cannot_change_access():void {$f=$this->fixture();$f['admin']->forceFill(['auth_version'=>2])->save();$this->actingAs($f['admin']);$this->withSession(['auth_version'=>1])->post('/centre-planning/governance/role/'.$f['other']->id,['version'=>0,'revision'=>$this->rev(),'role'=>'centre_manager','note'=>'No','confirmed'=>1])->assertRedirect();$this->assertDatabaseCount('timetable_governance_roles',0);}
 public function test_role_proof_tamper_fails_closed():void {$f=$this->fixture();$this->role($f['admin'],$f['other'],'viewer');DB::table('timetable_governance_roles')->where('user_id',$f['other']->id)->update(['role'=>'centre_manager']);$this->assertFalse(P::allowed($f['other']));}
 public function test_state_proof_tamper_holds_non_ceo():void {$f=$this->fixture();DB::table('timetable_governance_state')->update(['revision'=>99]);$this->assertFalse(P::allowed($f['admin']));$ceo=User::factory()->create(['role'=>'ceo']);$this->assertTrue(P::allowed($ceo));}
 public function test_required_audit_failure_rolls_back_role_and_global_revision():void {$f=$this->fixture();$rev=$this->rev();AuditFault::install('governance_fault','timetable_governance_events','Fictional failure','role_changed');try{$this->role($f['admin'],$f['other']);$this->fail('Expected failure');}catch(\Illuminate\Database\QueryException){$this->assertDatabaseCount('timetable_governance_roles',0);$this->assertSame($rev,$this->rev());}}
 public function test_notes_and_role_history_are_encrypted_at_rest():void {$f=$this->fixture();$this->role($f['admin'],$f['other']);foreach(['timetable_governance_events'=>'payload','timetable_governance_roles'=>'history','timetable_governance_state'=>'details']as$t=>$c){$this->assertStringNotContainsString('Fictional reviewed',DB::table($t)->orderByDesc($t==='timetable_governance_roles'?'user_id':'id')->value($c));}}
 public function test_existing_planner_grant_is_preserved_but_explicit_viewer_wins():void {$f=$this->fixture();$this->assertTrue(P::allowed($f['planner']));$this->role($f['admin'],$f['planner'],'viewer');$this->assertFalse(P::allowed($f['planner']));$this->reject(fn()=>P::grant($f['admin'],1,$f['planner'],1,true));$this->role($f['admin'],$f['planner'],'inherit');$this->assertTrue(P::allowed($f['planner']));}
 public function test_restricting_allocation_blocks_check_save_and_cover_prepare():void {$f=$this->fixture();$p=P::save($f['planner'],1,null,0,(string)Str::uuid(),$f['d']);G::allocation($f['admin'],1,$p,0,$this->rev(),true,false,'Fictional hold');$this->reject(fn()=>P::check($f['planner'],1,$p,1,true));$this->reject(fn()=>P::save($f['planner'],1,$p,1,$p->request_token,$f['d']));$this->assertSame(1,$p->refresh()->version);}
 public function test_ceo_can_release_allocation_protection_and_other_managers_cannot():void {$f=$this->fixture();$p=$this->plan($f);$ceo=User::factory()->create(['role'=>'ceo']);G::allocation($ceo,1,$p,0,$this->rev(),true,true,'Fictional CEO hold');$this->reject(fn()=>G::allocation($f['admin'],1,$p,1,$this->rev(),false,false,'No'));$this->reject(fn()=>P::withdraw($f['admin'],1,$p,3,'No'));G::allocation($ceo,1,$p,1,$this->rev(),false,false,'Fictional release');P::withdraw($f['admin'],1,$p,3,'Released');$this->assertTrue(P::withdrawn($p->refresh()));}
 public function test_ceo_can_withdraw_locked_published_series_without_removing_control():void {$f=$this->fixture();$p=$this->plan($f);$ceo=User::factory()->create(['role'=>'ceo']);G::allocation($ceo,1,$p,0,$this->rev(),true,true,'Hold');P::withdraw($ceo,1,$p,3,'CEO reconciliation');$this->assertTrue(P::withdrawn($p->refresh()));$this->assertTrue(Control::find($p->id)->ceo_locked);}
 public function test_active_cover_cannot_be_withdrawn_through_locked_allocation():void {$f=$this->fixture();$c=$this->activate($f);$p=Plan::find($c->source['basis']['plan_id']);G::allocation($f['admin'],1,$p,0,$this->rev(),true,false,'Hold');$this->reject(fn()=>C::withdraw($f['planner'],1,$c,3,'No'));$this->assertTrue(C::active($c->refresh()));}
 public function test_section_changes_do_not_grant_planning_or_change_primary_role():void {$f=$this->fixture();G::saveSection($f['admin'],1,$f['other'],0,$this->rev(),'other','Display only');$this->assertSame('other',G::section($f['other']));$this->assertFalse(P::allowed($f['other']));$this->assertSame('tutor',$f['other']->fresh()->role);$this->assertDatabaseCount('timetable_governance_roles',0);}
 public function test_section_is_stable_across_week_and_activity_changes():void {$f=$this->fixture();G::saveSection($f['admin'],1,$f['tutor'],0,$this->rev(),'other','Display only');$this->plan($f);foreach([$f['date'],today()->addMonths(3)->toDateString()]as$date){$b=T::board($f['admin'],$date);$res=collect($b['resources'])->firstWhere('id',$f['tutor']->id);$this->assertSame('Other staff',$res['section']);}}
 public function test_section_tamper_is_held_without_changing_permissions():void {$f=$this->fixture();G::saveSection($f['admin'],1,$f['other'],0,$this->rev(),'other','Display');DB::table('timetable_staff_sections')->update(['section'=>'teaching']);$this->assertSame('review',G::section($f['other']));$this->assertFalse(P::allowed($f['other']));}
 public function test_section_failure_rolls_back_and_stale_section_rejected():void {$f=$this->fixture();G::saveSection($f['admin'],1,$f['other'],0,$this->rev(),'other','Display');$this->reject(fn()=>G::saveSection($f['admin'],1,$f['other'],0,$this->rev(),'teaching','Stale'));$this->assertSame('other',G::section($f['other']));}
 public function test_staff_can_read_shared_published_board_but_not_other_private_titles_notes_or_grants():void {$f=$this->fixture();D::brief($f['planner'],1,$f['group'],0,null,'SECRET-SHARED-NOTE');$this->plan($f);$this->actingAs($f['other'])->get('/centre-planning?scope=staff&week='.$f['date'])->assertOk()->assertSee('Staff timetable')->assertSee('Teaching tutors')->assertDontSee('Fictional whole-day class')->assertDontSee('SECRET-SHARED-NOTE')->assertDontSee('Roles &amp; CEO control',false);$this->get('/centre-planning?scope=manage')->assertForbidden();$this->get('/centre-planning/governance')->assertForbidden();$this->get('/centre-planning.json?scope=staff')->assertForbidden();}
 public function test_shared_projection_contains_no_learner_roster_or_source_proof_or_private_availability():void {$f=$this->fixture();$this->plan($f);$b=T::board($f['other'],$f['date'],'staff',null,null,true,true);$this->assertCount(1,$b['rows']);foreach($b['rows']as$row){$this->assertSame([],$row['members']);$this->assertNull($row['plan_id']);$this->assertArrayNotHasKey('seal',$row);$this->assertArrayNotHasKey('link_proof',$row);$this->assertArrayNotHasKey('training_session_id',$row);}foreach($b['cells']as$days){foreach($days as$cell){$this->assertNull($cell['window']);$this->assertFalse($cell['known']);$this->assertSame([],$cell['gaps']);$this->assertNull($cell['flexible']);}}}
 public function test_own_view_remains_personal_and_shared_section_filter_works():void {$f=$this->fixture();$this->plan($f);$this->actingAs($f['other'])->get('/centre-planning?scope=own&week='.$f['date'])->assertOk()->assertDontSee('Fictional whole-day class');$this->get('/centre-planning?scope=staff&section=other&week='.$f['date'])->assertOk()->assertDontSee('Teaching — published diary');$this->get('/centre-planning?scope=staff&section=unknown')->assertSessionHasErrors('section');}
 public function test_shared_read_cannot_be_used_by_employers_or_apprentices():void {$f=$this->fixture();foreach(['employer','apprentice']as$role){$u=User::factory()->create(['role'=>$role]);$this->actingAs($u)->get('/centre-planning?scope=staff')->assertForbidden();}}
 public function test_governance_forms_require_confirmation_and_do_not_accept_ceo_role():void {$f=$this->fixture();$this->actingAs($f['admin'])->post('/centre-planning/governance/role/'.$f['other']->id,['version'=>0,'revision'=>$this->rev(),'role'=>'ceo','note'=>'No'])->assertSessionHasErrors('confirmed');$this->assertDatabaseCount('timetable_governance_roles',0);}
 public function test_shared_read_and_governance_do_not_change_registers_or_send_messages():void {Mail::fake();Http::preventStrayRequests();$f=$this->fixture();$this->role($f['admin'],$f['other']);$this->plan($f);$this->actingAs($f['other'])->get('/centre-planning?scope=staff&week='.$f['date'])->assertOk()->assertHeader('Referrer-Policy','no-referrer');foreach(['training_sessions','attendance_marks','historical_otj_records','signed_review_records']as$t){$this->assertDatabaseCount($t,0);}Mail::assertNothingSent();Http::assertNothingSent();}
}
